using System.Text.RegularExpressions;
using Sandlada.Okyct.Application;
using Sandlada.Okyct.Domain.Models;
using Sandlada.Okyct.Ports.Inbound;
using Sandlada.Okyct.Ports.Outbound;
using static Sandlada.Okyct.Domain.Services.ColorScience;

namespace Sandlada.Okyct.Adapters;

public sealed partial class TokenExporter : ITokenExporterPort
{
    private const string Header = "/* ==========================================================================\n" +
        "   Generated by OKYCT Studio (Production Design Tokens)\n" +
        "   ========================================================================== */";

    private static readonly StateLayer[] AllStates = [StateLayer.Hovered, StateLayer.Focused, StateLayer.Pressed, StateLayer.Dragged];

    public string ExportTheme(OkyctTheme theme, ExportThemeOptions? options = null)
    {
        ArgumentNullException.ThrowIfNull(theme);
        var p = theme.Palettes;
        PaletteSet<ITonalPalettePort> palettes = new(p.Primary, p.Secondary, p.Tertiary, p.Neutral,
            p.NeutralVariant, p.Error, p.Warning, p.Success, p.Info);
        return ExportTheme(new ExportThemeInput(theme.LightScheme, theme.DarkScheme, palettes,
            CustomColorsLight: theme.LightCustomColors, CustomColorsDark: theme.DarkCustomColors), options);
    }

    public string ExportTheme(ExportThemeInput input, ExportThemeOptions? options = null)
    {
        ArgumentNullException.ThrowIfNull(input);
        options ??= new();
        if (input.Palettes is null && input.SourceHex is { } seed)
        {
            var p = Palettes.CreatePalettesFromSource(seed, new CreatePalettesOptions(input.Variant, input.HarmonizeSemantics));
            input = input with { Palettes = new(p.Primary, p.Secondary, p.Tertiary, p.Neutral, p.NeutralVariant,
                p.Error, p.Warning, p.Success, p.Info) };
        }

        return options.Format switch
        {
            TokenExportFormat.Css => ExportCssVariables(input, options),
            TokenExportFormat.Tailwind => ExportTailwindV4(input, options),
            TokenExportFormat.W3c => ExportW3cDesignTokens(input, options),
            TokenExportFormat.Ts => ExportTypeScriptTokens(input, options),
            _ => throw new ArgumentOutOfRangeException(nameof(options))
        };
    }

    public string ExportCssVariables(ExportThemeInput input, ExportThemeOptions? options = null)
    {
        ArgumentNullException.ThrowIfNull(input);
        options ??= new();
        if (!Enum.IsDefined(options.CssSchemeMode)) throw new ArgumentOutOfRangeException(nameof(options));

        var light = SystemEntries(input.LightScheme, options);
        var dark = SystemEntries(input.DarkScheme, options);
        var palette = PaletteBlock(input.Palettes, options.ColorFormat);
        if (options.CssSchemeMode == CssSchemeMode.LightDark)
        {
            var values = light.Select(token => Line("--md-sys-color-" + KebabCase(token.Key),
                LightDark(token.Value, dark.GetValueOrDefault(token.Key, token.Value))));
            var customs = PairedCssCustomEntries(input, options).Select(token =>
                Line("--md-custom-color-" + token.Key, LightDark(token.Light, token.Dark)));
            return Header + "\n\n:root {\n  color-scheme: light dark;\n" +
                (palette.Length == 0 ? "" : "\n" + palette + "\n") + "\n" +
                Comment("System Colors — light-dark(light, dark)") + "\n" + string.Join('\n', values) +
                CustomBlock(customs) + "\n}\n";
        }

        string Block(Dictionary<string, string> system, Dictionary<string, string> custom, string mode) =>
            "." + mode.ToLowerInvariant() + " {\n" + Comment(mode + " Scheme System Colors") + "\n" +
            string.Join('\n', system.Select(token => Line("--md-sys-color-" + KebabCase(token.Key), token.Value))) +
            CustomBlock(custom.Select(token => Line("--md-custom-color-" + token.Key, token.Value))) + "\n}\n";
        return Header + "\n" + (palette.Length == 0 ? "" : "\n:root {\n" + palette + "\n}\n") + "\n" +
            Block(light, CssCustomEntries(input.CustomColorsLight, options), "Light") + "\n" +
            Block(dark, CssCustomEntries(input.CustomColorsDark, options), "Dark");
    }

    public string ExportTailwindV4(ExportThemeInput input, ExportThemeOptions? options = null)
    {
        ArgumentNullException.ThrowIfNull(input);
        options ??= new();
        if (!Enum.IsDefined(options.TailwindFallback)) throw new ArgumentOutOfRangeException(nameof(options));

        var keys = new HashSet<string>(StringComparer.Ordinal);
        var light = SystemEntries(input.LightScheme, options);
        var dark = SystemEntries(input.DarkScheme, options);
        string Alias(string key, string prefix, string l, string r)
        {
            if (!keys.Add(key)) throw new ArgumentException($"Token key collision: {key}");
            var suffix = options.TailwindFallback == TailwindFallbackMode.LightDark ? ", " + LightDark(l, r) : "";
            return Line("--color-" + key, $"var({prefix}{key}{suffix})");
        }

        var system = light.Select(entry => Alias(KebabCase(entry.Key), "--md-sys-color-", entry.Value,
            dark.GetValueOrDefault(entry.Key, entry.Value))).ToArray();
        var custom = PairedCssCustomEntries(input, options)
            .Select(entry => Alias(entry.Key, "--md-custom-color-", entry.Light, entry.Dark)).ToArray();

        return "/* Tailwind CSS v4 Theme Extension */\n@import \"tailwindcss\";\n" +
            "@custom-variant dark (&:where(.dark, .dark *));\n\n@theme {\n" +
            string.Join('\n', system) + (custom.Length == 0 ? "" :
                "\n\n  /* Custom Extended Semantic Tokens */\n" + string.Join('\n', custom)) + "\n}\n";
    }

    public string ExportW3cDesignTokens(ExportThemeInput input, ExportThemeOptions? options = null)
    {
        ArgumentNullException.ThrowIfNull(input);
        options ??= new();

        static object Leaf(string value, string description) =>
            new Dictionary<string, string> { ["$value"] = value, ["$type"] = "color", ["$description"] = description };

        Dictionary<string, object> Group(DynamicSchemeColors scheme, IReadOnlyList<ResolvedCustomColor>? custom)
        {
            var group = new Dictionary<string, object>(StringComparer.Ordinal);
            var system = SystemEntries(scheme, options);
            foreach (var (key, value) in system)
                Add(group, key, Leaf(value, SystemColorTokens.Values.Contains(key)
                    ? $"Material Design 3 system token for {key}" : $"Pre-composited state layer token for {key}"));
            foreach (var color in custom ?? [])
            {
                var slots = CustomRoles(color);
                var fields = new Dictionary<string, object>(StringComparer.Ordinal);
                foreach (var role in slots)
                    fields.Add(role.Key, Leaf(FormatColor(role.Hex, options.ColorFormat), color.Label + " " + role.Description));
                foreach (var role in slots)
                foreach (var (state, hex) in CustomStates(color, role, options.StateLayers))
                    fields.Add(role.Key + state, Leaf(FormatColor(hex, options.ColorFormat),
                        color.Label + " " + role.StateDescription + state.ToString().ToLowerInvariant() + " state layer"));
                Add(group, color.Name, fields);
            }
            return group;
        }

        return CanonicalJsonWriter.Serialize(new Dictionary<string, object>(StringComparer.Ordinal)
        {
            ["color"] = new Dictionary<string, object>(StringComparer.Ordinal)
            {
                ["light"] = Group(input.LightScheme, input.CustomColorsLight),
                ["dark"] = Group(input.DarkScheme, input.CustomColorsDark)
            }
        });
    }

    public string ExportTypeScriptTokens(ExportThemeInput input, ExportThemeOptions? options = null)
    {
        ArgumentNullException.ThrowIfNull(input);
        options ??= new();

        string Format(DynamicSchemeColors scheme, IReadOnlyList<ResolvedCustomColor>? custom)
        {
            var tokens = SystemEntries(scheme, options).ToDictionary(pair => pair.Key, pair => (object)pair.Value, StringComparer.Ordinal);
            var customEntries = new Dictionary<string, object>(StringComparer.Ordinal);
            foreach (var color in custom ?? [])
            {
                var roles = CustomRoles(color);
                var fields = roles.ToDictionary(role => role.Key, role => FormatColor(role.Hex, options.ColorFormat), StringComparer.Ordinal);
                foreach (var role in roles)
                foreach (var (state, hex) in CustomStates(color, role, options.StateLayers))
                    fields.Add(role.Key + state, FormatColor(hex, options.ColorFormat));
                Add(customEntries, color.Name, fields);
            }
            tokens["custom"] = customEntries;
            return CanonicalJsonWriter.Serialize(tokens);
        }

        return "/**\n * OKYCT Typed Color Tokens\n */\n\n" +
            "export const LightThemeTokens = " + Format(input.LightScheme, input.CustomColorsLight) + " as const\n\n" +
            "export const DarkThemeTokens = " + Format(input.DarkScheme, input.CustomColorsDark) + " as const\n\n" +
            "export type ThemeColors = typeof LightThemeTokens\n";
    }

    private static Dictionary<string, string> SystemEntries(DynamicSchemeColors scheme, ExportThemeOptions options)
    {
        ArgumentNullException.ThrowIfNull(scheme);
        if (!Enum.IsDefined(options.ColorFormat)) throw new ArgumentOutOfRangeException(nameof(options));
        var result = SystemColorTokens.Values.ToDictionary(key => key,
            key => FormatColor(scheme[key], options.ColorFormat,
                scheme.Okyct.TryGetValue(key, out var coordinate) ? coordinate : null), StringComparer.Ordinal);
        var states = options.StateLayers is { } requested
            ? DynamicSchemes.ResolveSchemeStateLayers(scheme, requested)
            : scheme.StateLayers;
        foreach (var (key, fallback) in states ?? new Dictionary<string, string>())
        {
            var hex = scheme.StateLayers?.GetValueOrDefault(key, fallback) ?? fallback;
            result[key] = FormatColor(hex, options.ColorFormat);
        }
        return result;
    }

    private static Dictionary<string, string> CssCustomEntries(
        IReadOnlyList<ResolvedCustomColor>? custom, ExportThemeOptions options)
    {
        var result = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var color in custom ?? [])
        {
            var name = KebabCase(color.Name);
            if (name.Length == 0) throw new ArgumentException("Expected a non-empty custom color name.");
            foreach (var role in CustomRoles(color))
            {
                var key = (role.Key.StartsWith("on", StringComparison.Ordinal) ? "on-" : "") + name +
                    (role.Key.EndsWith("Container", StringComparison.Ordinal) ? "-container" : "");
                Add(result, key, FormatColor(role.Hex, options.ColorFormat));
                foreach (var (state, hex) in CustomStates(color, role, options.StateLayers))
                    Add(result, key + "-" + state.ToString().ToLowerInvariant(), FormatColor(hex, options.ColorFormat));
            }
        }
        return result;
    }

    private static IEnumerable<(string Key, string Light, string Dark)> PairedCssCustomEntries(
        ExportThemeInput input, ExportThemeOptions options)
    {
        var darkByName = new Dictionary<string, ResolvedCustomColor>(StringComparer.Ordinal);
        foreach (var color in input.CustomColorsDark ?? []) darkByName[color.Name] = color;
        var keys = new HashSet<string>(StringComparer.Ordinal);
        foreach (var light in input.CustomColorsLight ?? [])
        {
            var dark = CssCustomEntries([darkByName.GetValueOrDefault(light.Name, light)], options);
            foreach (var (key, value) in CssCustomEntries([light], options))
            {
                if (!keys.Add(key)) throw new ArgumentException($"Token key collision: {key}");
                yield return (key, value, dark.GetValueOrDefault(key, value));
            }
        }
    }

    private static IEnumerable<(StateLayer State, string Hex)> CustomStates(
        ResolvedCustomColor color, CustomRole role, IReadOnlyList<StateLayer>? requested)
    {
        foreach (var state in (requested ?? AllStates).Distinct())
        {
            if (state is < StateLayer.Hovered or > StateLayer.Dragged) throw new ArgumentOutOfRangeException(nameof(requested));
            if (color.StateLayers?.TryGetValue(role.Key + state, out var existing) == true)
                yield return (state, existing);
            else if (requested is not null)
                yield return (state, LayerStacking.StackStateLayers([state])(new(role.Hex, role.Overlay)).FinalHex);
        }
    }

    private static CustomRole[] CustomRoles(ResolvedCustomColor c) =>
    [
        new("color", c.Color, c.OnColor, "base role", ""),
        new("onColor", c.OnColor, c.Color, "foreground text", "on-color "),
        new("colorContainer", c.ColorContainer, c.OnColorContainer, "tonal container", "container "),
        new("onColorContainer", c.OnColorContainer, c.ColorContainer, "container text", "container on-color ")
    ];

    private static string PaletteBlock(PaletteSet<ITonalPalettePort>? palettes, CssColorFormat format)
    {
        if (palettes is null) return "";
        (string Name, ITonalPalettePort Palette)[] roles =
        [
            ("primary", palettes.Primary), ("secondary", palettes.Secondary), ("tertiary", palettes.Tertiary),
            ("neutral", palettes.Neutral), ("neutral-variant", palettes.NeutralVariant), ("error", palettes.Error),
            ("warning", palettes.Warning), ("success", palettes.Success), ("info", palettes.Info)
        ];
        var entries = from role in roles
                      from tone in StandardTones.Values
                      select Line($"--md-ref-palette-{role.Name}-{tone}", role.Palette.ToneCss(tone, format));
        return Comment("Reference Tonal Palettes (13 Standard Stops)") + "\n" + string.Join('\n', entries);
    }

    internal static string FormatColor(string hex, CssColorFormat format, OkyctColor? coordinate = null) => format switch
    {
        CssColorFormat.Hex => hex,
        CssColorFormat.Oklch => OkyctToOklchCss(coordinate ?? HexToOkyct(hex)),
        CssColorFormat.DisplayP3 => OkyctToDisplayP3Css(coordinate ?? HexToOkyct(hex)),
        _ => throw new ArgumentOutOfRangeException(nameof(format))
    };

    internal static string[] Words(string text)
    {
        var spaced = Regex.Replace(text, "([a-z0-9])([A-Z])", "$1 $2");
        spaced = Regex.Replace(spaced, "([A-Z]+)([A-Z][a-z])", "$1 $2");
        return Regex.Split(TrimAsciiWhitespace(spaced), "[-_ \\t\\n\\r\\f]+").Where(word => word.Length != 0).ToArray();
    }

    internal static string KebabCase(string text) => string.Join('-', Words(text).Select(word => word.ToLowerInvariant()));

    private static string Comment(string text) =>
        "  /* -------------------------------------------------------------\n     " + text +
        "\n     ------------------------------------------------------------- */";

    private static string CustomBlock(IEnumerable<string> entries)
    {
        var text = string.Join('\n', entries);
        return text.Length == 0 ? "" : "\n\n" + Comment("Custom Extended Semantic Colors") + "\n" + text;
    }

    private static string Line(string key, string value) => $"  {key}: {value};";
    private static string LightDark(string light, string dark) => $"light-dark({light}, {dark})";

    internal static void Add<T>(Dictionary<string, T> dictionary, string key, T value)
    {
        if (!dictionary.TryAdd(key, value)) throw new ArgumentException($"Token key collision: {key}");
    }

    private sealed record CustomRole(string Key, string Hex, string Overlay, string Description, string StateDescription);
}
